<template><section class="alert-config" v-loading="loading"><header class="heading"><div><h1>库存预警配置</h1><p>为库存管理 Item 设置公司默认阈值，并可按仓库设置覆盖规则。</p></div><div><el-button @click="$router.push('/inventory/alerts')">返回预警列表</el-button><el-button :loading="saving" @click="save(false)">保存草稿</el-button><el-button type="success" :disabled="!item.id" :loading="saving" @click="save(true)">保存并启用</el-button></div></header><el-alert title="预警使用真实可用库存：账面库存 - 已锁定/预留 - 不合格/待处理。仓库规则优先于公司默认规则。" type="info" :closable="false" show-icon/><main class="grid"><section class="card item"><h2>Item基础信息</h2><dl><dt>Item编码</dt><dd>{{item.item_code||'-'}}</dd><dt>Item名称</dt><dd>{{item.item_name||'-'}}</dd><dt>Item类目</dt><dd>{{item.category&&item.category.category_name||'-'}}</dd><dt>基本单位</dt><dd>{{item.unit&&(item.unit.symbol||item.unit.unit_name)||'-'}}</dd><dt>库存管理</dt><dd><el-tag size="mini" type="success">{{item.is_stock_item?'是':'否'}}</el-tag></dd></dl><el-button type="text" icon="el-icon-arrow-right" :disabled="!item.id" @click="$router.push(`/inventory/balances?item_id=${item.id}`)">查看库存余额</el-button></section><section class="card form"><h2>公司默认预警阈值</h2><div class="switch-line"><span>启用库存预警</span><el-switch v-model="form.enabled" active-color="#07883f" active-text="启用" inactive-text="停用"/></div><div class="thresholds"><label>最低库存<el-input-number v-model="form.min_stock" :min="0" controls-position="right"/><small>{{unit}}</small></label><label>安全库存<el-input-number v-model="form.safety_stock" :min="0" controls-position="right"/><small>{{unit}}</small></label><label>最高库存<el-input-number v-model="form.max_stock" :min="0" controls-position="right"/><small>{{unit}}</small></label><label>建议补货数量<el-input-number v-model="form.suggested_replenishment_qty" :min="0" controls-position="right"/><small>{{unit}}</small></label></div><div class="rule"><h3>仓库覆盖规则 <el-button type="text" icon="el-icon-plus" @click="addOverride">新增仓库规则</el-button></h3><el-table :data="overrides" border size="small"><el-table-column label="仓库" min-width="150"><template slot-scope="{row}"><el-select v-model="row.warehouse_id" filterable placeholder="请选择"><el-option v-for="w in warehouses" :key="w.id" :label="w.warehouse_name" :value="w.id"/></el-select></template></el-table-column><el-table-column label="最低库存" min-width="105"><template slot-scope="{row}"><el-input-number v-model="row.min_stock" :min="0" controls-position="right"/></template></el-table-column><el-table-column label="安全库存" min-width="105"><template slot-scope="{row}"><el-input-number v-model="row.safety_stock" :min="0" controls-position="right"/></template></el-table-column><el-table-column label="最高库存" min-width="105"><template slot-scope="{row}"><el-input-number v-model="row.max_stock" :min="0" controls-position="right"/></template></el-table-column><el-table-column label="建议补货" min-width="105"><template slot-scope="{row}"><el-input-number v-model="row.suggested_replenishment_qty" :min="0" controls-position="right"/></template></el-table-column><el-table-column label="操作" width="74"><template slot-scope="{$index}"><el-button type="text" class="danger" @click="overrides.splice($index,1)">删除</el-button></template></el-table-column></el-table></div><p class="state"><i class="el-icon-info"/> 状态说明：可用库存≤最低库存为严重低库存；≤安全库存为低库存；超过最高库存为超储；恢复后自动解除。</p></section><section class="card check"><h2>保存前检查</h2><ul><li :class="item.id?'yes':'no'"><i class="el-icon-circle-check"/>已选择库存 Item</li><li :class="valid?'yes':'no'"><i class="el-icon-circle-check"/>阈值关系有效</li><li class="yes"><i class="el-icon-circle-check"/>仓库覆盖优先级明确</li><li class="yes"><i class="el-icon-circle-check"/>预警状态变更会保存历史</li></ul><div class="states"><h3>状态与通知</h3><p><el-tag type="warning" size="mini">低库存</el-tag> 可用库存 ≤ 安全库存</p><p><el-tag type="danger" size="mini">缺货</el-tag> 可用库存 = 0</p><p><el-tag type="info" size="mini">超储</el-tag> 可用库存 ＞ 最高库存</p><p><el-tag type="success" size="mini">恢复</el-tag> 状态恢复正常后通知</p></div></section></main></section></template>
<script>
import { getInventoryAlertPolicy, saveInventoryAlertPolicy, activateInventoryAlertPolicy, disableInventoryAlertPolicy } from '@/api/erp/inventory';import { listEntity } from '@/api/erp/master';
const empty=()=>({enabled:true,min_stock:null,safety_stock:null,max_stock:null,suggested_replenishment_qty:null});
export default{name:'InventoryAlertConfiguration',data:()=>({loading:false,saving:false,item:{},warehouses:[],form:empty(),overrides:[]}),computed:{unit(){return this.item.unit&&(this.item.unit.symbol||this.item.unit.unit_name)||'PCS'},valid(){const f=this.form;const required=[f.min_stock,f.safety_stock,f.suggested_replenishment_qty].every(v=>v!==null&&v!==''&&Number(v)>=0);const maxEmpty=f.max_stock===null||f.max_stock==='';return required&&Number(f.min_stock)<=Number(f.safety_stock)&&(maxEmpty||Number(f.safety_stock)<=Number(f.max_stock))}},created(){this.init()},methods:{async init(){this.loading=true;try{const [w]=await Promise.all([listEntity('warehouses',{per_page:100})]);this.warehouses=w.data.data||[];if(this.$route.query.item_id)await this.load(this.$route.query.item_id)}catch(e){this.$message.error(e.userMessage||'预警配置加载失败')}finally{this.loading=false}},async load(id){const r=await getInventoryAlertPolicy(id);this.item=r.data.item||{};const policies=r.data.policies||[];const company=policies.find(x=>x.scope_key==='company');if(company)this.form={...empty(),...company,enabled:company.is_enabled};this.overrides=policies.filter(x=>x.scope_key!=='company').map(x=>({...x,enabled:x.is_enabled}))},addOverride(){this.overrides.push({...empty(),warehouse_id:null})},async save(activate){if(!this.valid)return this.$message.error('最低库存、安全库存、建议补货数量为必填；最高库存为空或不小于安全库存。');this.saving=true;try{const fn=activate?activateInventoryAlertPolicy:saveInventoryAlertPolicy;await fn(this.item.id,{...this.form});for(const row of this.overrides.filter(x=>x.warehouse_id)){await fn(this.item.id,{...row})}this.$message.success(activate?'库存预警规则已启用':'库存预警草稿已保存');await this.load(this.item.id)}catch(e){this.$message.error(e.userMessage||'保存失败')}finally{this.saving=false}}}}
</script>
<style scoped>
.alert-config{min-height:calc(100vh - 52px);padding:22px 24px;background:#f7f9fb;color:#172033;box-sizing:border-box}.heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:16px}.heading h1{margin:0 0 7px;font-size:28px}.heading p{margin:0;color:#6d798a;font-size:14px}.heading .el-button{height:40px;margin-left:10px}.heading .el-button--success{background:#07883f;border-color:#07883f}.el-alert{margin-bottom:14px;border:1px solid #b8d7ff;background:#f4f9ff}.grid{display:grid;grid-template-columns:250px minmax(620px,1fr) 270px;gap:14px}.card{padding:18px;border:1px solid #e1e7ee;border-radius:7px;background:#fff}.card h2{margin:0 0 17px;font-size:17px}.item dl{display:grid;grid-template-columns:82px 1fr;gap:18px 8px;margin:0;padding:13px 0 20px;border-top:1px solid #e8edf2}.item dt{color:#6d798a}.item dd{margin:0;word-break:break-word}.item>.el-button{padding:0;color:#1677ff}.switch-line{display:flex;justify-content:space-between;padding:14px 0 18px;border-top:1px solid #e8edf2;font-size:14px}.thresholds{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.thresholds label{position:relative;display:flex;flex-direction:column;gap:7px;font-size:13px}.thresholds .el-input-number{width:100%}.thresholds small{position:absolute;right:12px;bottom:8px;color:#788595;pointer-events:none}.rule{margin-top:18px}.rule h3{display:flex;justify-content:space-between;align-items:center;font-size:15px;margin:0 0 11px}.rule h3 .el-button{color:#07883f}.rule :deep(.el-input-number){width:100%}.danger{color:#e24242}.state{margin:17px 0 0;padding:10px 12px;border:1px solid #b8d7ff;border-radius:5px;background:#f4f9ff;color:#3471c8;font-size:12px}.state i{font-size:16px;margin-right:4px}.check ul{padding:0;margin:0;list-style:none}.check li{padding:11px 0;border-bottom:1px solid #e8edf2;font-size:13px}.check li i{font-size:18px;margin-right:7px}.yes{color:#07883f}.no{color:#e24242}.states{margin-top:18px;border:1px solid #e1e7ee;border-radius:5px;padding:12px}.states h3{margin:0 0 12px;font-size:15px}.states p{margin:9px 0;font-size:12px}@media(max-width:1200px){.grid{grid-template-columns:210px minmax(540px,1fr) 230px}.thresholds{grid-template-columns:repeat(2,1fr)}}@media(max-width:980px){.grid{grid-template-columns:1fr}.thresholds{grid-template-columns:repeat(4,1fr)}}@media(max-width:720px){.alert-config{padding:16px 12px}.heading{display:block}.heading>div:last-child{margin-top:12px}.heading .el-button{margin-left:0;margin-right:8px}.thresholds{grid-template-columns:repeat(2,1fr)}.rule{overflow-x:auto}.rule .el-table{min-width:720px}}
</style>
